def invoke(self, role, tool, action, *, metadata=None):
    if tool not in CAPABILITIES.get(role, set()): raise ValueError("ROLE_TOOL_NOT_ALLOWED")
    self.calls.append({"role": role, "tool": tool, "remote_calls": 0, **(metadata or {})})
